SELECT CASE WHEN c.credit_limit >= 15600 THEN 'high' WHEN c.credit_limit >= 3900 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, c.city, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(s.browser))) AS browser_values, MIN(s.started_at) AS min_started_at FROM sessions s INNER JOIN customers c ON s.customer_id = c.id GROUP BY CASE WHEN c.credit_limit >= 15600 THEN 'high' WHEN c.credit_limit >= 3900 THEN 'mid' ELSE 'low' END, c.city
